insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('a8c64df5-f7f8-5a08-ad27-662e2daede3b', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BN0', 'Topic 1: Lifestyle, Health and Risk', 0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('39819512-8f68-5b8f-a93c-bbccebe859c7', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.1', 'Understand why many animals have a heart and circulation (mass transport to overcome limitations of diffusion in meeting the requirements of organisms).', 0, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8fe8e986-0be1-5bdd-aabe-2d7b9dfb826d', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.2', 'Understand the importance of water as a solvent in transport, including its dipole nature.', 1, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e65d8fad-2743-5a99-83f3-06886ecc79dc', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.3', 'Understand how the structures of blood vessels (capillaries, arteries and veins) relate to their functions.', 2, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9d71945b-cf24-5ef9-8e33-6e04840d09ab', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.4', 'i) Know the cardiac cycle (atrial systole, ventricular systole and cardiac diastole) and relate the structure and operation of the mammalian heart, including the major blood vessels, to its function. ii) Know how the relationship between heart structure and function can be investigated practically.', 3, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9c3bbb77-bd1e-5834-a4e0-75eb9dcde3a6', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.5', 'Understand the course of events that leads to atherosclerosis (endothelial dysfunction, inflammatory response, plaque formation, raised blood pressure).', 4, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3cab3394-2866-578e-a3c3-09e6922cacb6', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.6', 'Understand the blood-clotting process (thromboplastin release, conversion of prothrombin to thrombin and fibrinogen to fibrin) and its role in cardiovascular disease (CVD).', 5, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('83ceba89-9ead-590d-972a-a98f41d17c15', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.7', 'Know how factors such as genetics, diet, age, gender, high blood pressure, smoking and inactivity increase the risk of cardiovascular disease (CVD).', 6, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d1dbe280-437c-517a-ba87-f1ec3d68cac8', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.8', 'Be able to analyse and interpret quantitative data on illness and mortality rates to determine health risks, including distinguishing between correlation and causation and recognising conflicting evidence.', 7, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('25785cbe-4b81-5db3-8093-dfbfaef90a15', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.9', 'Be able to evaluate the design of studies used to determine health risk factors, including sample selection and sample size used to collect data that is both valid and reliable.', 8, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('19ad7f76-0b0d-5d5e-9000-53b3f449daaf', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.10', 'Understand why people''s perceptions of risks are often different from the actual risks, including underestimating and overestimating the risks due to diet and other lifestyle factors in the development of heart disease.', 9, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1dbcba47-45ea-5842-8c5d-219b074766de', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.11', 'i) Be able to analyse data on energy budgets and diet. ii) Understand the consequences of energy imbalance, including weight loss, weight gain, and development of obesity.', 10, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8fae0f3d-7e94-5b63-8bf8-0a8ac92cfb23', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.12', 'i) Know the difference between monosaccharides, disaccharides and polysaccharides, including glycogen and starch (amylose and amylopectin). ii) Be able to relate the structures of monosaccharides, disaccharides and polysaccharides to their roles in providing and storing energy (β-glucose and cellulose are not required in this topic).', 11, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7f8379f5-bf71-552a-a32c-3feaed7bd4cc', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.13', 'Know how monosaccharides join to form disaccharides (sucrose, lactose and maltose) and polysaccharides (glycogen and amylose) through condensation reactions forming glycosidic bonds, and how these can be split through hydrolysis reactions.', 12, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('24af248e-dd27-5194-853d-c10c961793ed', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.14', 'i) Know how a triglyceride is synthesised by the formation of ester bonds during condensation reactions between glycerol and three fatty acids. ii) Know the differences between saturated and unsaturated lipids.', 13, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b5ef970f-89f3-5231-9027-35bdb77a3bc2', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.15', 'i) Be able to analyse and interpret data on the possible significance for health of blood cholesterol levels and levels of high-density lipoproteins (HDLs) and low-density lipoproteins (LDLs). ii) Know the evidence for a causal relationship between blood cholesterol levels (total cholesterol and LDL cholesterol) and cardiovascular disease (CVD).', 14, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('56ca4f9f-c954-5f25-b8f7-e67e25ecb4f4', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.16', 'Understand how people use scientific knowledge about the effects of diet, including obesity indicators, body mass index and waist-to-hip ratio, exercise and smoking to reduce their risk of coronary heart disease.', 15, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('675b8510-e456-50e2-894b-6054ef3476ca', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.17', 'Be able discuss the potential ethical issues regarding the use of invertebrates in research.', 16, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e769e1b0-6375-520f-affd-196096e5a1e9', 'a8c64df5-f7f8-5a08-ad27-662e2daede3b', '1.18', 'Know the benefits and risks of treatments for cardiovascular disease (CVD) (antihypertensives, statins, anticoagulants and platelet inhibitors).', 17, 1) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('1654f0fd-c6c1-59a0-8815-25448750a3d8', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BN0', 'Topic 2: Genes and Health', 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('188de98b-b251-5cbe-a5c2-5cc5fc52a622', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.1', 'i) Know the properties of gas exchange surfaces in living organisms (large surface area to volume ratio, thickness of surface, difference in concentration). ii) Understand how the rate of diffusion is dependent on these properties and can be calculated using Fick''s Law of Diffusion. iii) Understand how the structure of the mammalian lung is adapted for rapid gaseous exchange.', 0, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('372ab1d7-b74e-5cca-83c5-84b53acfd245', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.2', 'i) Know the structure and properties of cell membranes. ii) Understand how models such as the fluid mosaic model of cell membranes are interpretations of data used to develop scientific explanations of the structure and properties of cell membranes.', 1, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0288eefd-76d8-5e63-881d-1d1ce4fdb9c3', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.3', 'Understand what is meant by osmosis in terms of the movement of free water molecules through a partially permeable membrane (consideration of water potential is not required).', 2, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7bd2f7c3-270c-5376-ae1e-c1c091d90e16', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.4', 'i) Understand what is meant by passive transport (diffusion, facilitated diffusion), active transport (including the role of ATP as an immediate source of energy), endocytosis and exocytosis. ii) Understand the involvement of carrier and channel proteins in membrane transport.', 3, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('603d45e6-bb71-52b9-9212-70285a058ea5', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.5', 'i) Know the basic structure of mononucleotides (deoxyribose or ribose linked to a phosphate and a base, including thymine, uracil, cytosine, adenine or guanine) and the structures of DNA and RNA (polynucleotides composed of mononucleotides linked through condensation reactions). ii) Know how complementary base pairing and the hydrogen bonding between two complementary strands are involved in the formation of the DNA double helix.', 4, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1ff86a90-82ef-5fd2-8459-6c446f9a9d6c', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.6', 'i) Understand the process of protein synthesis (transcription) including the role of RNA polymerase, translation, messenger RNA, transfer RNA, ribosomes and the role of start and stop codons. ii) Understand the roles of the DNA template (antisense) strand in transcription, codons on messenger RNA and anticodons on transfer RNA.', 5, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f4c50128-7c31-5ac3-87c2-76a69d40b27a', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.7', 'Understand the nature of the genetic code (triplet code, non-overlapping and degenerate).', 6, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('747a3441-f20b-5039-aef5-1712c99d3aff', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.8', 'Know that a gene is a sequence of bases on a DNA molecule that codes for a sequence of amino acids in a polypeptide chain.', 7, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ad86973d-66f1-5053-81a3-3b539b479bf3', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.9', 'i) Know the basic structure of an amino acid (structures of specific amino acids are not required). ii) Understand the formation of polypeptides and proteins (amino acid monomers linked by peptide bonds in condensation reactions). iii) Understand the significance of a protein''s primary structure in determining its three-dimensional structure and properties (globular and fibrous proteins and the types of bonds involved in its three-dimensional structure). iv) Know the molecular structure of a globular protein and a fibrous protein and understand how their structures relate to their functions (including haemoglobin and collagen).', 8, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('97ac8cfc-aede-5362-8e09-35714c3556b5', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.10', 'i) Understand the mechanism of action and the specificity of enzymes in terms of their three-dimensional structure. ii) Understand that enzymes are biological catalysts that reduce activation energy. iii) Know that there are intracellular enzymes catalysing reactions inside cells and extracellular enzymes produced by cells catalysing reactions outside of cells.', 9, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3dc2efc1-f56a-5354-a06d-eb1e3dc146a0', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.11', 'i) Understand the process of DNA replication, including the role of DNA polymerase. ii) Understand how Meselson and Stahl''s classic experiment provided new data that supported the accepted theory of replication of DNA and refuted competing theories.', 10, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4cecd5f0-828e-5ae7-8459-5cfcbd1d2e47', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.12', 'i) Understand how errors in DNA replication can give rise to mutations. ii) Understand how cystic fibrosis results from one of a number of possible gene mutations.', 11, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('41b61fa8-39a9-51f9-bb3f-f3173518768f', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.13', 'i) Know the meaning of the terms: gene, allele, genotype, phenotype, recessive, dominant, incomplete dominance, homozygote and heterozygote. ii) Understand patterns of inheritance, including the interpretation of genetic pedigree diagrams, in the context of monohybrid inheritance.', 12, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d9505777-da39-5281-92d9-fe2b27c9571d', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.14', 'Understand how the expression of a gene mutation in people with cystic fibrosis impairs the functioning of the gaseous exchange, digestive and reproductive systems.', 13, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('aabf627d-e306-5d26-866d-9bf195172046', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.15', 'i) Understand the uses of genetic screening, including the identification of carriers, pre-implantation genetic diagnosis (PGD) and prenatal testing, including amniocentesis and chorionic villus sampling. ii) Understand the implications of prenatal genetic screening.', 14, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6910f608-8c2a-597a-bfeb-d09633089077', '1654f0fd-c6c1-59a0-8815-25448750a3d8', '2.16', 'Be able to identify and discuss the social and ethical issues related to genetic screening from a range of ethical viewpoints.', 15, 1) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BN0', 'Topic 3: Voice of the Genome', 2) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('957eda20-b841-5fa4-bd52-333f3635e85d', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.1', 'Know that all living organisms are made of cells, sharing some common features.', 0, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2a1a1468-d5e6-5f84-9149-c475c6274a8c', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.2', 'Know the ultrastructure of eukaryotic cells, including nucleus, nucleolus, ribosomes, rough and smooth endoplasmic reticulum, mitochondria, centrioles, lysosomes, and Golgi apparatus.', 1, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f5e16f8b-f25e-5bb2-a5ff-9ea5fb302bfe', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.3', 'Understand the role of the rough endoplasmic reticulum (rER) and the Golgi apparatus in protein transport within cells, including their role in the formation of extracellular enzymes.', 2, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('af5d3306-5f7e-5a51-9e9d-3aabc59b692c', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.4', 'Know the ultrastructure of prokaryotic cells, including cell wall, capsule, plasmid, flagellum, pili, ribosomes, mesosomes and circular DNA.', 3, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ffa31af1-8c21-5b97-b98c-c867b2671798', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.5', 'Be able to recognise the organelles in 3.2 from electron microscope (EM) images.', 4, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6ed2c92b-3b0b-5c51-ac01-4ee2319bd789', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.6', 'Understand how mammalian gametes are specialised for their functions (including the acrosome in sperm and the zona pellucida in the egg).', 5, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f9f69124-fbff-5a3d-acca-ae849827583b', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.7', 'Know the process of fertilisation in mammals, including the acrosome reaction, the cortical reaction and the fusion of nuclei.', 6, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ec005e95-36d3-554e-a807-fb40c32828f8', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.8', 'i) Know that a locus (plural = loci) is the location of genes on a chromosome. ii) Understand the linkage of genes on a chromosome and sex linkage.', 7, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('948715a4-6e32-5a2e-9e17-64221a835ad0', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.9', 'Understand the role of meiosis in ensuring genetic variation through the production of non-identical gametes as a consequence of independent assortment of chromosomes and crossing over of alleles between chromatids (details of the stages of meiosis are not required).', 8, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e2e000cf-1c69-54ff-88d5-b38d3c0e08fc', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.10', 'Understand the role of mitosis and the cell cycle in producing identical daughter cells for growth and asexual reproduction.', 9, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('dc993672-34bd-5810-b11a-2b23b026c5c1', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.11', 'i) Understand what is meant by the terms ''stem cell, pluripotency and totipotency''. ii) Be able to discuss the way society uses scientific knowledge to make decisions about the use of stem cells in medical therapies.', 10, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c0563636-afb7-52e9-93b0-f2d1e8ba73f6', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.12', 'Understand how cells become specialised through differential gene expression, producing active mRNA leading to synthesis of proteins, which in turn control cell processes or determine cell structure in animals and plants, including the lac operon.', 11, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('dd7eaca9-109a-5dc7-9a55-719f8b8915a8', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.13', 'Understand how the cells of multicellular organisms are organised into tissues, tissues into organs and organs into systems.', 12, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b2b3b3df-9848-57aa-af46-12b33986abdb', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.14', 'i) Understand how phenotype is the result of an interaction between genotype and the environment. ii) Know how epigenetic changes, including DNA methylation and histone modification, can modify the activation of certain genes. iii) Understand how epigenetic changes can be passed on following cell division.', 13, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2454fecb-4506-587d-810b-50d06b1711f4', 'cca79b5f-6dd3-55c5-b4d5-9f095ecdba7b', '3.15', 'Understand how some phenotypes are affected by multiple alleles for the same gene at many loci (polygenic inheritance) as well as the environment and how this can give rise to phenotypes that show continuous variation.', 14, 1) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('e97c16e9-32fc-5e90-81fb-de48f28e480c', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BN0', 'Topic 4: Biodiversity and Natural Resources', 3) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1eea4489-8216-5acb-a799-46503cc6e2fb', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.1', 'Know that over time the variety of life has become extensive but is now being threatened by human activity.', 0, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d2157a76-ddee-5d23-afc6-9d12a3bd161b', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.2', 'i) Understand the terms biodiversity and endemism. ii) Know how biodiversity can be measured within a habitat using species richness and within a species using genetic diversity by calculating the heterozygosity index (H): iii) Understand how biodiversity can be compared in different habitats using a formula to calculate an index of diversity (D):', 1, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('74c061e8-3924-5431-a8de-8fcee0684fdd', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.3', 'Understand the concept of niche and be able to discuss examples of adaptation of organisms to their environment (behavioural, physiological and anatomical).', 2, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7ff8432f-d4ba-52ae-a0a6-b0a8f2cb1ea3', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.4', 'Understand how natural selection can lead to adaptation and evolution. number of heterozygotesH = number of individuals in the population ( ) ( ) NN 1D Σn n 1 −= −', 3, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ac478c1f-c88f-53a0-b034-8c79a946c768', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.5', 'i) Understand how the Hardy-Weinberg equation can be used to see whether a change in allele frequency is occurring in a population over time. ii) Understand that reproductive isolation can lead to accumulation of different genetic information in populations, potentially leading to the formation of new species.', 4, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('3e9e09ad-1532-58b0-a643-2da3c8d8a3cc', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.6', 'i) Understand that classification is a means of organising the variety of life based on relationships between organisms using differences and similarities in phenotypes and in genotypes, and is built around the species concept. ii) Understand the process and importance of critical evaluation of new data by the scientific community, which leads to new taxonomic groupings, including the three domains of life based on molecular phylogeny, which are Bacteria, Archaea, Eukaryota.', 5, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('242bb616-6832-5982-97e6-058ddc8038f6', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.7', 'Know the ultrastructure of plant cells (cell walls, chloroplasts, amyloplasts, vacuole, tonoplast, plasmodesmata, pits and middle lamella) and be able to compare it with animal cells.', 6, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0d590450-be6f-55e6-be4a-2270971f1406', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.8', 'Be able to recognise the organelles in 4.7 from electron microscope (EM) images.', 7, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('75f0b7b6-9f20-5ec3-88c6-689f532c8869', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.9', 'Understand the structure and function of the polysaccharides starch and cellulose, including the role of hydrogen bonds between β-glucose molecules in the formation of cellulose microfibrils.', 8, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c2fde1e8-0c40-5404-b8af-ba9c7f3a138d', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.10', 'Understand how the arrangement of cellulose microfibrils and secondary thickening in plant cell walls contributes to the physical properties of xylem vessels and sclerenchyma fibres in plant fibres that can be exploited by humans.', 9, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('584f59d3-fda9-587f-b5f1-a8dd61a0736b', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.11', 'Know the similarities and differences between the structures, position in the stem and function of sclerenchyma fibres (support), xylem vessels (support and transport of water and mineral ions) and phloem (translocation of organic solutes).', 10, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ffbb15cb-4031-5387-a822-f0fbe456f5a6', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.12', 'Understand the importance of water and inorganic ions (nitrate, calcium ions and magnesium ions) to plants.', 11, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7a9113b6-eb1f-5c84-a15d-8fbc4e9b4a36', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.13', 'Understand the development of drug testing from historic to contemporary protocols, including William Withering''s digitalis soup, double blind trials, placebo, three-phased testing.', 12, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('42dd8a64-9c13-5033-8ad6-fda5c684ba37', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.14', 'Understand the conditions required for bacterial growth.', 13, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4494e4ea-bb84-5d9a-bb37-9615ffbe42c8', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.15', 'Understand how the uses of plant fibres and starch may contribute to sustainability, including plant-based products to replace oil-based plastics.', 14, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e6cad7c4-de51-5757-a3bd-e1d9d6117330', 'e97c16e9-32fc-5e90-81fb-de48f28e480c', '4.16', 'Be able to evaluate the methods used by zoos and seed banks in the conservation of endangered species and their genetic diversity, including scientific research, captive breeding programmes, reintroduction programmes and education.', 15, 1) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('c7c5b84d-8df8-5661-a32d-238fd7538235', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BN0', 'Topic 5: On the Wild Side', 4) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2f6da1e2-cb65-51c1-a3ad-d29dd696fca3', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.1', 'Understand the terms ecosystem, community, population and habitat.', 0, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b841e68d-4f57-51d2-b272-40f9e7987e3d', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.2', 'Understand that the numbers and distribution of organisms in a habitat are controlled by biotic and abiotic factors.', 1, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e6cdd8e4-cb79-53b3-8ca0-28d65bf21c67', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.3', 'Understand how the concept of niche accounts for distribution and abundance of organisms in a habitat.', 2, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6adc1929-f333-5d93-9aac-943801941f96', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.4', 'Understand the stages of succession from colonisation to a climax community.', 3, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a593e0f1-2ffe-507c-abcb-c437fd68f8f4', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.5', 'Understand the overall reaction of photosynthesis as requiring energy from light to split apart the strong bonds in water molecules, storing the hydrogen in a fuel (glucose) by combining it with carbon dioxide and releasing oxygen into the atmosphere.', 4, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('60c0ab1c-1f5f-515c-bc0c-7d983d49e047', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.6', 'Understand how phosphorylation of ADP requires energy and that hydrolysis of ATP provides an immediate supply of energy for biological processes.', 5, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f152d1b0-1072-5aec-822d-cde48f30b471', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.7', 'Understand the light-dependent reactions of photosynthesis including how light energy is trapped by exciting electrons in chlorophyll and the role of these electrons in generating ATP, reducing NADP in photophosphorylation and producing oxygen through photolysis of water.', 6, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('02ecaf77-2f52-5f1e-8f4a-333ae0c1c104', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.8', 'i) Understand the light-independent reactions as reduction of carbon dioxide using the products of the light-dependent reactions (carbon fixation in the Calvin cycle, the role of GP, GALP, RuBP and RUBISCO). ii) Know that the products are simple sugars that are used by plants, animals and other organisms in respiration and the synthesis of new biological molecules (polysaccharides, amino acids, lipids and nucleic acids).', 7, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d5180166-cc50-5888-8bb8-efba37b3b8b8', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.9', 'Understand the structure of chloroplasts in relation to their role in photosynthesis.', 8, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c146a10d-4965-53c0-8a04-4972820fa926', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.10', 'i) Be able to calculate net primary productivity. ii) Understand the relationship between gross primary productivity, net primary productivity and plant respiration.', 9, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('890cae0d-3c0c-5b4e-8783-cf4d6535465c', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.11', 'Know how to calculate the efficiency of biomass and energy transfers between trophic levels.', 10, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8e36bccf-9a64-52a4-a8ec-4b2485177f3d', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.12', 'Understand the different types of evidence for climate change and its causes (including records of carbon dioxide levels, temperature records, pollen in peat bogs and dendrochronology), recognising correlations and causal relationships.', 11, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('11c68eaa-efb2-51d0-8816-a8e4b7a9c3ce', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.13', 'Understand the causes of anthropogenic climate change, including the role of greenhouse gases (carbon dioxide and methane) in the greenhouse effect.', 12, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d233401e-91dc-52b3-bd42-c7c20cd35b3f', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.14', 'i) Understand that data can be extrapolated to make predictions and that these are used in models of future climate change. ii) Understand that models for climate change have limitations.', 13, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b0aa56c9-e66b-50ad-9a14-2ae6f2e31399', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.15', 'Understand the effects of climate change (changing rainfall patterns and changes in seasonal cycles) on plants and animals (distribution of species, development and life cycles).', 14, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d00b6b5e-6b0d-5b07-8e58-d329992ddf31', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.16', 'Understand the effect of temperature on the rate of enzyme activity and its impact on plants, animals and microorganisms.', 15, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8a1a5d0f-bc05-51ed-bb6a-7340450d58ff', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.17', 'Understand how evolution (a change in the allele frequency) can come about through gene mutation and natural selection.', 16, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f1dc1dbe-31ee-54d1-beea-1baab54794b9', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.18', 'Understand the role of the scientific community (scientific journals, the peer review process, scientific conferences) in validating new evidence, including proteomics and genomics, that supports the accepted scientific theory of evolution.', 17, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('609c7f6e-2223-553c-bfc0-7757b33df875', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.19', 'Understand how isolation reduces gene flow between populations, leading to allopatric or sympatric speciation.', 18, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f878fa05-45ac-56f5-b5fe-dab82b05ff2d', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.20', 'Understand the way in which scientific conclusions about controversial issues, such as what actions should be taken to reduce climate change or the degree to which humans are affecting climate change, can sometimes depend on who is reaching the conclusions.', 19, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('245d4068-5f02-5935-bc9d-fc9a3d83983d', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.21', 'Understand how knowledge of the carbon cycle can be applied to methods to reduce atmospheric levels of carbon dioxide.', 20, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c2a28ee6-7811-5872-9e6d-9a314de7dc7b', 'c7c5b84d-8df8-5661-a32d-238fd7538235', '5.22', 'Understand how reforestation and the use of sustainable resources, including biofuels, are examples of the effective management of the conflict between human needs and conservation.', 21, 1) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('0872468b-6006-5b40-84ca-55f58f7ae355', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BN0', 'Topic 6: Immunity, Infection and Forensics', 5) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('21dce271-4f23-524c-8170-dcfd6eb15781', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.1', 'Understand how to determine the time of death of a mammal by examining the extent of decomposition, stage of succession, forensic entomology, body temperature and degree of muscle contraction.', 0, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('5a3d3f09-72d3-5c51-9524-1f649eb26b11', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.2', 'Know the role of micro-organisms in the decomposition of organic matter and the recycling of carbon.', 1, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('cfc0d42c-0dc8-54a2-bfef-5fcb976bd693', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.3', 'Know how DNA profiling is used for identification and determining genetic relationships between organisms (plants and animals).', 2, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d673a02a-ef18-54f0-8990-65b6e9bef30d', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.4', 'Know how DNA can be amplified using the polymerase chain reaction (PCR).', 3, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1f9a5ba1-f2cf-50a9-b67f-25dca3c248a3', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.5', 'Be able to compare the structure of bacteria and viruses.', 4, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4bb9a800-39a8-5df0-adf4-d5b344024efc', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.6', 'Understand how Mycobacterium tuberculosis (TB) and Human Immunodeficiency Virus (HIV) infect human cells, causing a sequence of symptoms that may result in death.', 5, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('01aff25d-4f38-577f-bb23-b9a3a9990c42', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.7', 'Understand the non-specific responses of the body to infection, including inflammation, lysozyme action, interferon, and phagocytosis.', 6, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c79ae735-0d2c-58d6-ad85-62b25265f758', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.8', 'Understand the roles of antigens and antibodies in the body''s immune response including the involvement of plasma cells, macrophages and antigen-presenting cells.', 7, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6cf5c4bb-605f-5047-9101-329a1ba82e0d', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.9', 'Understand the differences between the roles of B cells (B memory and B effector cells) and T cells (T helper, T killer and T memory cells) in the body''s immune response.', 8, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('da4ab5c7-f037-5a4a-b276-842fe2db7ec6', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.10', 'Understand how one gene can give rise to more than one protein through post- transcriptional changes to messenger RNA (mRNA).', 9, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b863416a-b2bf-5eb5-b93b-93b766a44ab8', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.11', 'i) Know the major routes pathogens may take when entering the body. ii) Understand the role of barriers in protecting the body from infection, including skin, stomach acid, and gut and skin flora.', 10, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f9a97344-389b-5c26-8746-5d88f7786641', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.12', 'Understand how individuals may develop immunity (natural, artificial, active, passive).', 11, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('fb7f9941-d378-5aeb-9262-7fcabf29a56d', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.13', 'Understand how the theory of an ''evolutionary race'' between pathogens and their hosts is supported by the evasion mechanisms shown by pathogens.', 12, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('41d69514-42aa-5c0c-a5d0-74d10553cfbe', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.14', 'Understand the difference between bacteriostatic and bactericidal antibiotics.', 13, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f8c80567-435d-5ffb-85b3-053cb5b84b58', '0872468b-6006-5b40-84ca-55f58f7ae355', '6.15', 'Know how an understanding of the contributory causes of hospital acquired infections have led to codes of practice regarding antibiotic prescription and hospital practice that relate to infection prevention and control.', 14, 1) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('1f703e09-916c-52a0-abf4-72fcc697ba2f', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BN0', 'Topic 7: Run for your Life', 6) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d6d94a1f-42cf-5808-b5f4-8a98087fef6a', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.1', 'Know the way in which muscles, tendons, the skeleton and ligaments interact to enable movement, including antagonistic muscle pairs, extensors and flexors.', 0, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0b1ebc8d-538a-5bed-af0d-19f83ad9a10b', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.2', 'Understand the process of contraction of skeletal muscle in terms of the sliding filament theory, including the role of actin, myosin, troponin, tropomyosin, calcium ions (Ca 2+), ATP and ATPase.', 1, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ef4e52f7-f219-54e4-9afb-5ec2d72a5dbd', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.3', 'i) Understand the overall reaction of aerobic respiration as splitting of the respiratory substrate, to release carbon dioxide as a waste product and reuniting of hydrogen with atmospheric oxygen with the release of a large amount of energy. ii) Understand that respiration is a many-stepped process with each step controlled and catalysed by a specific intracellular enzyme.', 2, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8dc02c88-5a23-57c8-b10b-ebdf74c98c33', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.4', 'Understand the roles of glycolysis in aerobic and anaerobic respiration, including the phosphorylation of hexoses, the production of ATP, reduced coenzyme, pyruvate and lactate (details of intermediate stages and compounds are not required).', 3, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('146e0e33-7580-5f2f-8bdc-23c597e296ae', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.5', 'Understand the role of the link reaction and the Krebs cycle in the complete oxidation of glucose and formation of carbon dioxide (CO2), ATP, reduced NAD and reduced FAD (names of other compounds are not required) and why these steps take place in the mitochondria, unlike glycolysis which occurs in the cytoplasm.', 4, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('445d0cbd-7f8b-551c-8655-9716a1934168', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.6', 'Understand how ATP is synthesised by oxidative phosphorylation associated with the electron transport chain in mitochondria, including the role of chemiosmosis and ATP synthase.', 5, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('188be3a1-fe99-575e-b012-d53891f2374f', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.7', 'Understand what happens to lactate after a period of anaerobic respiration in animals.', 6, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('fc27f2fc-e40c-507a-80b5-b3fbdd95c84a', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.8', 'i) Know the myogenic nature of cardiac muscle. ii) Understand how the normal electrical activity of the heart coordinates the heart beat, including the roles of the sinoatrial node (SAN), the atrioventricular node (AVN), the bundle of His and the Purkyne fibres. iii) Understand how the use of electrocardiograms (ECGs) can aid the diagnosis of cardiovascular disease (CVD) and other heart conditions.', 7, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('dd54f3c1-218c-5aa2-a49a-9f9150d707b1', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.9', 'i) Be able to calculate cardiac output. ii) Understand how variations in ventilation and cardiac output enable rapid delivery of oxygen to tissues and the removal of carbon dioxide from them, including how the heart rate and ventilation rate are controlled and the roles of the cardiovascular control centre and the ventilation centre in the medulla oblongata.', 8, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e5bcc57c-c31a-5517-a29e-db373289cb08', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.10', 'i) Know the structure of a muscle fibre. ii) Understand the structural and physiological differences between fast and slow twitch muscle fibres.', 9, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('cb8d623d-1df0-5b89-8ce5-a6cb42069a11', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.11', 'i) Understand what is meant by negative feedback and positive feedback control. ii) Understand the principle of negative feedback in maintaining systems within narrow limits.', 10, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('388465f0-efa9-5045-bec5-a33f3d694f64', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.12', 'Understand homeostasis and its importance in maintaining the body in a state of dynamic equilibrium during exercise, including the role of the hypothalamus and the mechanisms of thermoregulation.', 11, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f0f507bc-b9ad-546a-89d8-2acc44d1687b', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.13', 'Understand the analysis and interpretation of data relating to possible disadvantages of exercising too much (wear and tear on joints, suppression of the immune system) and exercising too little (increased risk of obesity, cardiovascular disease (CVD) and diabetes), recognising correlation and causal relationships.', 12, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e1d11e8f-2b33-545a-b9c0-43c096c0e77e', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.14', 'Understand how medical technology, including the use of keyhole surgery and prostheses, is enabling those with injuries and disabilities to participate in sports.', 13, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('71ac4ca1-53f3-50bc-baf2-54d20be96316', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.15', 'Be able to discuss different ethical positions relating to whether the use of performance-enhancing substances by athletes is acceptable.', 14, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('749444a2-1a6e-540a-aa66-8c3fcea4bb85', '1f703e09-916c-52a0-abf4-72fcc697ba2f', '7.16', 'Understand how genes can be switched on and off by DNA transcription factors including hormones.', 15, 1) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('4400be78-801f-57a0-8d5e-236b5857370e', 'biology'::public.subject, 'edexcel'::public.board, 'alevel'::public.level, '9BN0', 'Topic 8: Grey Matter', 7) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('9dee2366-d6fc-57c8-9862-654cf9273f3e', '4400be78-801f-57a0-8d5e-236b5857370e', '8.1', 'Know the structure and function of sensory, relay and motor neurones including the role of Schwann cells and myelination.', 0, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b6a3395b-4858-5143-9f5b-d6d853cb4dfd', '4400be78-801f-57a0-8d5e-236b5857370e', '8.2', 'i) Understand how the nervous systems of organisms can cause effectors to respond to a stimulus. ii) Understand how the pupil dilates and contracts.', 1, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('715158d3-7174-5379-a645-0bc9bc10d5eb', '4400be78-801f-57a0-8d5e-236b5857370e', '8.3', 'Understand how a nerve impulse (action potential) is conducted along an axon including changes in membrane permeability to sodium and potassium ions and the role of the myelination in saltatory conduction.', 2, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('58ba54ad-4baf-5a26-bbf0-3fffa4c8e301', '4400be78-801f-57a0-8d5e-236b5857370e', '8.4', 'Know the structure and function of synapses in nerve impulse transmission, including the role of neurotransmitters, including acetylcholine.', 3, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d0646ddd-fe11-5d33-beea-7cb368c6df60', '4400be78-801f-57a0-8d5e-236b5857370e', '8.5', 'Understand how the nervous systems of organisms can detect stimuli with reference to rods in the retina of mammals, the roles of rhodopsin, opsin, retinal, sodium ions, cation channels and hyperpolarisation of rod cells in forming action potentials in the optic neurones.', 4, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('bd4759f0-1f62-5868-a5d5-978082e8cf81', '4400be78-801f-57a0-8d5e-236b5857370e', '8.6', 'Understand how phytochrome and IAA bring about responses in plants to environmental cues, including their effects on transcription.', 5, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('406ab568-e216-5fef-813b-00ec997ccb1b', '4400be78-801f-57a0-8d5e-236b5857370e', '8.7', 'Understand how co-ordination is brought about through nervous and hormonal control in animals.', 6, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('96a94e0d-4406-5b86-9857-3992ae9629de', '4400be78-801f-57a0-8d5e-236b5857370e', '8.8', 'Know the location and functions of the cerebral hemispheres, hypothalamus, cerebellum and medulla oblongata in the human brain.', 7, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('674e632d-1807-5f95-a1fa-09b665139e0e', '4400be78-801f-57a0-8d5e-236b5857370e', '8.9', 'Understand how magnetic resonance imaging (MRI), functional magnetic resonance imaging (fMRI), positron emission tomography (PET) and computed tomography (CT) scans are used in medical diagnosis and the investigation of brain structure and function.', 8, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('210d85ed-1e66-51e5-b048-dbb52d451591', '4400be78-801f-57a0-8d5e-236b5857370e', '8.10', 'Understand what happens during the critical period so that mammals can develop their visual capacities to the full.', 9, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a684cd4f-a305-55b5-a46c-7d6a47b8380e', '4400be78-801f-57a0-8d5e-236b5857370e', '8.11', 'Understand the role animal models have played in the research into human brain development and function, including Hubel and Wiesel''s experiments with monkeys and kittens.', 10, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a78485dd-0a7c-50da-8292-9622d1a63a53', '4400be78-801f-57a0-8d5e-236b5857370e', '8.12', 'Be able to discuss moral and ethical issues relating to the use of animals in medical research from two ethical standpoints.', 11, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('eed107e6-0434-5863-8591-022251fb6f54', '4400be78-801f-57a0-8d5e-236b5857370e', '8.13', 'Understand how animals, including humans, can learn by habituation.', 12, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d495d90d-a2eb-52ab-b478-be5b1a1a7bb5', '4400be78-801f-57a0-8d5e-236b5857370e', '8.14', 'Understand how imbalances in certain, naturally occurring brain chemicals can contribute to ill health, including dopamine in Parkinson''s disease and serotonin in depression, and to the development of new drugs.', 13, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('51463112-f7b1-5ffa-bc09-3702bf4de26e', '4400be78-801f-57a0-8d5e-236b5857370e', '8.15', 'Understand the effects of drugs on synaptic transmissions, including the use of L-Dopa in the treatment of Parkinson''s disease and the action of MDMA in Ecstasy.', 14, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('be9c7096-aa23-5eee-b862-88f29822d6b0', '4400be78-801f-57a0-8d5e-236b5857370e', '8.16', 'Understand how the outcomes of genome sequencing projects are being used in the development of personalised medicine and the social, moral and ethical issues this raises.', 15, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2b0cae6f-99b5-5f53-8a2e-c2bcda802148', '4400be78-801f-57a0-8d5e-236b5857370e', '8.17', 'Know how drugs can be produced using genetically modified organisms (plants, animals and microorganisms).', 16, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7a29aedd-f9cb-5274-b2c3-bfd28f9403f5', '4400be78-801f-57a0-8d5e-236b5857370e', '8.18', 'Understand the risks and benefits associated with the use of genetically modified organisms.', 17, 1) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('35dfe9cf-58eb-5d8f-a4b3-8bcb9d564429', '4400be78-801f-57a0-8d5e-236b5857370e', '8.19', 'Understand the methods used to investigate the contributions of nature and nurture to brain development, including evidence from the abilities of new-born babies, animal experiments, studies of individuals with damaged brain areas, twin studies and cross-cultural studies.', 18, 1) on conflict (id) do nothing;
